<div class="panel"><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:center"><h2 style="margin:0">Mes notifications</h2><?php if (array_filter($rows, fn($r) => !$r['read_at'])): ?><form method="post" action="/compte/notifications/lues"><?= csrf_field() ?><button class="btn btn-sm">Tout marquer comme lu</button></form><?php endif; ?></div>
<?php if (!$rows): ?><p class="muted">Aucune notification pour le moment. Les messages envoyés à propos de vos commandes et devis apparaîtront ici.</p><?php else: ?><ul class="timeline" style="margin-top:14px"><?php foreach ($rows as $r): $href = $r['oref'] ? '/commande/' . $r['oref'] . '?t=' . $r['otok'] : ($r['qref'] ? '/compte/devis' : ''); ?><li><b><?= e($r['subject']) ?></b><?= $r['read_at'] ? '' : ' <span class="badge b-warn">Nouveau</span>' ?><small><?= e(fdate($r['created_at'], true)) ?></small><?php if ($href): ?><br><a href="<?= e($href) ?>">Voir</a><?php endif; ?></li><?php endforeach; ?></ul><?php endif; ?></div>
